<span class="line">wssc <span class="token operator">=</span> u16<span class="token punctuation">(</span><span class="token number">92</span><span class="token punctuation">)</span> <span class="token operator">+</span> <span class="token builtin">bytes</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">47</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token operator">+</span> u16<span class="token punctuation">(</span><span class="token builtin">len</span><span class="token punctuation">(</span>body<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token operator">+</span> body</span>
